SELECT
hc.*,
s1.name AS communityProvinceName,
s2.name AS communityCityName,
s3.name AS communityTownName
FROM community hc
LEFT JOIN sys_area s1 ON hc.community_province_code = s1.code
LEFT JOIN sys_area s2 ON hc.community_city_code = s2.code
LEFT JOIN sys_area s3 ON hc.community_town_code = s3.code


        AND hc.community_id = #{community.communityId}


        AND hc.community_name LIKE CONCAT('%', #{community.communityName}, '%')


        AND hc.community_code LIKE CONCAT('%', #{community.communityCode}, '%')


        AND hc.community_province_code = #{community.communityProvinceCode}


        AND hc.community_city_code = #{community.communityCityCode}


        AND hc.community_town_code = #{community.communityTownCode}


        AND hc.dept_id = #{community.deptId}


        AND 1 = 0


        AND hc.community_id IN

